insert into public.stilnytsi_materials (slug, data, position) values ('tansky', '{"slug":"tansky","name":"Танський граніт (Tansky)","material":"granit","family":"Граніт","origin":"Кіровоградська область, Україна","tone":"сірий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади","бруківка"],"description":"Танський граніт — сірий камінь середнього зерна з Кіровоградщини, з яким працює половина українських виробників пам’ятників. Темніший за Покостівський, із виразнішими чорними вкрапленнями; на стільниці й сходи йде полірованим, на терасу термообробленим.","image":"/materials/tansky.webp","cardImage":"/materials/tansky.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 100) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('greenish-tansky', '{"slug":"greenish-tansky","name":"Північно-Танський граніт (Greenish Tansky)","material":"granit","family":"Граніт","origin":"Кіровоградська область, Україна","tone":"сіро-зелений","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["сходи","фасади","бруківка"],"description":"Північно-Танський граніт (Greenish Tansky) — сусіднє з Танським родовище, але з оливковим відтінком сірого. Це найспокійніший «зелений» камінь: на фасаді читається як сірий, зблизька видно зеленуваті кристали. Добре виглядає в бруківці й на зовнішніх сходах.","image":"/materials/greenish-tansky.webp","cardImage":"/materials/greenish-tansky.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 101) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('evening-warsaw', '{"slug":"evening-warsaw","name":"Західно-Танський граніт (Evening Warsaw)","material":"granit","family":"Граніт","origin":"Кіровоградська область, Україна","tone":"темно-сірий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Західно-Танський граніт (Evening Warsaw) — темно-сірий, майже графітовий, з дрібними чорними вкрапленнями і рівним тоном. Для тих, кому чорне габро здається надто темним, а світло-сірий надто буденним. Полірований на стільниці, термооброблений на сходи.","image":"/materials/evening-warsaw.webp","cardImage":"/materials/evening-warsaw.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 102) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('sophiyvsky', '{"slug":"sophiyvsky","name":"Софіївський граніт (Sophiyvsky)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"світло-сірий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади","бруківка"],"description":"Софіївський граніт — світло-сірий камінь із Житомирщини з теплим відтінком і дрібними чорними цятками. Один із найдоступніших українських гранітів, стабільні великі блоки, тому його часто беруть на довгі підвіконня, сходи й облицювання цоколя.","image":"/materials/sophiyvsky.webp","cardImage":"/materials/sophiyvsky.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":2400,"unit":"пог.м","currency":"грн"}}'::jsonb, 103) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('verde-oliva', '{"slug":"verde-oliva","name":"Маславський граніт (Verde Oliva)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"темно-зелений","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Маславський граніт (Verde Oliva) — темно-зелений дрібнозернистий камінь з оливковим відтінком. Зелений граніт рідкісний, і Маславський — найрівніший з українських: без плям і жил, тому підходить і на стільницю, і на фасад великими плитами.","image":"/materials/verde-oliva.webp","cardImage":"/materials/verde-oliva.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 104) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('real-grey', '{"slug":"real-grey","name":"Янцівський граніт (Real Grey)","material":"granit","family":"Граніт","origin":"Запорізька область, Україна","tone":"світло-сірий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади","бруківка"],"description":"Янцівський граніт (Real Grey) — світло-сірий дрібнозернистий камінь із Запорізької області, світліший і рівніший за Покостівський. Без плям і жил, добре тримає геометрію на великих плитах, тому це базовий вибір для світлих сходів і фасадного облицювання.","image":"/materials/real-grey.webp","cardImage":"/materials/real-grey.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 105) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('cardinal-grey', '{"slug":"cardinal-grey","name":"Жежелівський граніт (Cardinal Grey)","material":"granit","family":"Граніт","origin":"Вінницька область, Україна","tone":"сірий із блакитним відтінком","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Жежелівський граніт (Cardinal Grey) — сірий із легким блакитним відтінком і дрібними чорними цятками. Холодний тон підходить до сучасних кухонь із білими або графітовими фасадами; на терасах у термообробленому фініші стає світлішим і протиковзким.","image":"/materials/cardinal-grey.webp","cardImage":"/materials/cardinal-grey.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 106) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('grey-quoin', '{"slug":"grey-quoin","name":"Старобабанський граніт (Grey Quoin)","material":"granit","family":"Граніт","origin":"Черкаська область, Україна","tone":"сіро-рожевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["сходи","фасади","бруківка"],"description":"Старобабанський граніт (Grey Quoin) — сіре тло з рожевими вкрапленнями польового шпату, середнє зерно. Теплий сірий, який добре поєднується з червоним каменем і деревом. Найчастіше йде на бруківку, бордюри й зовнішні сходи.","image":"/materials/grey-quoin.webp","cardImage":"/materials/grey-quoin.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 107) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('kostyantynivsky', '{"slug":"kostyantynivsky","name":"Костянтинівський граніт","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"сірий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади","бруківка"],"description":"Костянтинівський граніт — дрібнозернистий холодний сірий із темними вкрапленнями. Дрібне зерно дає чіткі кромки й рівний тон на довгих виробах: підвіконнях, сходинках, стільницях без видимих швів.","image":"/materials/kostyantynivsky.webp","cardImage":"/materials/kostyantynivsky.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 108) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('boguslavsky', '{"slug":"boguslavsky","name":"Богуславський граніт","material":"granit","family":"Граніт","origin":"Київська область, Україна","tone":"сіро-рожевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["сходи","фасади","бруківка"],"description":"Богуславський граніт — сіро-рожевий камінь середньо-крупного зерна з Київщини, з помітними рожевими і чорними кристалами. Живіша поверхня, ніж у рівних сірих гранітів; добре виглядає в бруківці, на сходах і в облицюванні цоколя.","image":"/materials/boguslavsky.webp","cardImage":"/materials/boguslavsky.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 109) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('holovynske', '{"slug":"holovynske","name":"Головинське габро","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"глибокий чорний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","каміни","фасади"],"description":"Головинське габро — найглибший чорний серед українських каменів: без вкраплень, після полірування дзеркальна поверхня. Еталон під лазерне гравіювання, а в домі — чорні стільниці, каміни й акцентні стіни. Не має «рудих» включень, які з часом проступають на імпортних чорних гранітах.","image":"/materials/holovynske.webp","cardImage":"/materials/holovynske.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 110) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('bukynske', '{"slug":"bukynske","name":"Букинське габро","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"чорний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","каміни","сходи"],"description":"Букинське габро — насичений чорний із дуже дрібним зерном і найнижчим водопоглинанням серед габро, до 0,1 %. Не темніє від вологи й не боїться морозу, тому підходить і на кухню, і на зовнішні сходи. Полірований майже не відрізняється від Головинського, дешевший за лабрадорит.","image":"/materials/bukynske.webp","cardImage":"/materials/bukynske.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 111) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('antik-nero', '{"slug":"antik-nero","name":"Лугове габро (Antik Nero)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"чорний із сіро-зеленим відтінком","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["сходи","фасади","бруківка"],"description":"Лугове габро (Antik Nero) — чорний камінь із ледь помітним сіро-зеленим відтінком і середнім зерном. Найдоступніший чорний у нашому довіднику: на облицювання, бруківку й сходи, де потрібен темний камінь без преміальної ціни.","image":"/materials/antik-nero.webp","cardImage":"/materials/antik-nero.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 112) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('extra-blue-ukraine', '{"slug":"extra-blue-ukraine","name":"Добринський лабрадорит (Extra Blue Ukraine)","material":"granit","family":"Лабрадорит","origin":"Житомирська область, Україна","tone":"чорний із синім переливом","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","каміни","фасади"],"description":"Добринський лабрадорит (Extra Blue Ukraine) — чорне тло з великими кристалами, що спалахують яскраво-синім під кутом до світла. Найяскравіший перелив серед українських лабрадоритів; на стільниці й каміни береться полірованим, бо саме поліровка розкриває іризацію.","image":"/materials/extra-blue-ukraine.webp","cardImage":"/materials/extra-blue-ukraine.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 113) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('volga-blue-extra', '{"slug":"volga-blue-extra","name":"Горбулівський лабрадорит (Volga Blue Extra)","material":"granit","family":"Лабрадорит","origin":"Житомирська область, Україна","tone":"чорно-сірий із синьо-зеленим переливом","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","каміни","фасади"],"description":"Горбулівський лабрадорит (Volga Blue Extra) — чорно-сіре тло з найбільшими кристалами, перелив синьо-зелений. Кристали видно з відстані, тому камінь працює на великих площинах: стільниця острова, стіна каміна, фасадна плита.","image":"/materials/volga-blue-extra.webp","cardImage":"/materials/volga-blue-extra.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 114) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('black-ice', '{"slug":"black-ice","name":"Невирівський лабрадорит (Black Ice)","material":"granit","family":"Лабрадорит","origin":"Житомирська область, Україна","tone":"графітово-чорний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Невирівський лабрадорит (Black Ice) — графітово-чорний камінь майже без переливу, лише зрідка сріблясто-фіолетовий спалах. Щільніший за габро, тому не боїться морозу й механіки; вибір для тих, кому потрібен рівний чорний без ефектів.","image":"/materials/black-ice.webp","cardImage":"/materials/black-ice.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 115) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('berestovetskyi', '{"slug":"berestovetskyi","name":"Берестовецький базальт","material":"granit","family":"Граніт","origin":"Рівненська область, Україна","tone":"темно-сірий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["бруківка","сходи","фасади"],"description":"Берестовецький базальт — темно-сірий, майже чорний камінь із дуже дрібним зерном, кар’єр за 15 км від нашого цеху. Щільніший за граніт, матовіший за габро; класичний матеріал бруківки, бордюрів і цоколів, у полірованому вигляді йде на підвіконня.","image":"/materials/berestovetskyi.webp","cardImage":"/materials/berestovetskyi.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 116) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('kostopilskyi', '{"slug":"kostopilskyi","name":"Костопільський базальт","material":"granit","family":"Граніт","origin":"Рівненська область, Україна","tone":"темно-сірий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["бруківка","фасади","сходи"],"description":"Костопільський базальт — місцевий камінь Костопільщини: темно-сірий, дрібнозернистий, без рисунка. Найкоротша доставка й стабільні партії; бруківка, доріжки, облицювання цоколя й сходи на вулиці.","image":"/materials/kostopilskyi.webp","cardImage":"/materials/kostopilskyi.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 117) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('khustovskyi', '{"slug":"khustovskyi","name":"Хустовський базальт","material":"granit","family":"Граніт","origin":"Закарпатська область, Україна","tone":"сіро-чорний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["бруківка","фасади"],"description":"Хустовський базальт — закарпатський камінь із теплішим сіро-чорним тоном, ніж рівненські базальти, зрідка з дрібними порами. Колота бруківка, підпірні стінки й фасадне облицювання в природному фактурному вигляді.","image":"/materials/khustovskyi.webp","cardImage":"/materials/khustovskyi.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 118) on conflict (slug) do update set data = excluded.data;
